    var body = typeof c.body === 'string' ? c.body : '';
    if (body) return { body: body, inline: true, fromFile: false };
    if (c.comment && typeof readText === 'function') {
        return { body: readText(c.comment) || '', inline: false, fromFile: true };
    }
